const body = $input.first().json.body;
if (!body || typeof body !== 'object' || Array.isArray(body) || JSON.stringify(body).length > 100000) throw new Error('Invalid inquiry');
if (!['intro_contact_request','interest_registration'].includes(body.event)) throw new Error('Invalid event');
if (!['ai-help','app-idea','greenhouse-interest','legacy-card'].includes(body.intent)) throw new Error('Invalid intent');
if (body.website) throw new Error('Invalid inquiry');
const scrub = value => String(value).replace(/\b\d{3}-\d{2}-\d{4}\b/g,'[redacted]').replace(/\b(?:\d[ -]*?){13,19}\b/g,'[redacted]').replace(/\b(?:sk-|sb_secret_)[a-zA-Z0-9_-]{16,}\b/g,'[redacted]');
const context = {};
for (const [key,value] of Object.entries(body.context || {})) {
  if (!['business','task','result','idea','audience','problem','firstVersion','summary'].includes(key) || typeof value !== 'string' || value.length>1000) throw new Error('Invalid context');
  context[key] = scrub(value);
}
if (body.messages && (!Array.isArray(body.messages) || body.messages.length>60)) throw new Error('Invalid conversation');
const messages=(body.messages || []).map(turn=>{
  if (!turn || !['user','assistant'].includes(turn.role) || typeof turn.content!=='string' || turn.content.length>4000) throw new Error('Invalid conversation');
  return {role:turn.role,content:scrub(turn.content)};
});
return [{json:{p_payload:{requestId:body.requestId,event:body.event,intent:body.intent,source:body.source || 'direct',contactMethod:body.contactMethod,contact:{name:body.contact?.name,email:body.contact?.email || null,phone:body.contact?.phone || null},context,messages,business:typeof body.business==='string'?scrub(body.business):undefined,task:typeof body.task==='string'?scrub(body.task):undefined,consent:body.consent,testMode:body.testMode===true}}}];
